    def __init__(self):
        # We'll solve the 2-SAT problem with the constraint that each variable appears at most twice
        # Use union-find with negative tracking to detect contradictions

        # For each variable x_i:
        # - node (i, 0) represents x_i = true
        # - node (i, 1) represents x_i = false

    def solve(self, data):
        n, m, clauses = parse_input(data)

        # Build graph for implications
        # For a clause (l1 ∨ l2 ∨ ... ∨ lk), we add implications:
        # For each literal li, add implications (¬li → li) for all other literals lj
        # (The clause is satisfied if at least one literal is true, so if all others are false, this one must be true)

        # Since each variable appears at most twice, we can use a simpler approach:
        # Track possible assignments using union-find

        parent = list(range(2 * m))
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return True
            parent[px] = py
            return False

        # Track which variables are constrained
        var_in_clause = {}  # literal value -> set of clause indices
        literal_pos = {}  # (clause_idx, literal_value) -> list of other literals in clause

