            # In implications: ¬l1 → l2 ∨ ... ∨ lk, ¬l2 → l1 ∨ ... ∨ lk, etc.

            # For 2-SAT with k literals in clause, we add implications:
            for i in range(len(clause)):
                l = clause[i]
                # If l is false, some other literal in clause must be true
                if len(clause) > 1:
