        # For a clause (l1 ∨ l2 ∨ ...), ¬l1 → l2∨l3..., ¬l1∧¬l2 → l3∨...
        # etc.

        # Build implication graph for 2-SAT
        N = 2 * m
        adj = [[] for _ in range(N)]

        def literal_to_node(lit):
            """Convert literal to node: x_i true -> 2*i, x_i false -> 2*i+1"""
            x = abs(lit) - 1
            if lit > 0:
