    missing_positions = []

    for i, x in enumerate(a):
        if x != -1:
            used.add(x)
        else:
            missing_positions.append(i + 1)

    missing_values = set(range(1, n + 1)) - used

    # Count positions where position == value and both are missing
    d = 0
    for pos in missing_positions:
        if pos in missing_values:
            d += 1

    m = len(missing_positions)
    MOD = 1000000007

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Modular inverse using Fermat's little theorem
    def modInverse(n):
        return pow(n, MOD - 2, MOD)

    # Compute nCr mod MOD
    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = fact[n]
        den = (fact[r] * fact[n - r]) % MOD
        return (num * modInverse(den)) % MOD

    # Inclusion-exclusion: sum_{k=0}^{d} (-1)^k * C(d,k) * (m-k)!
    total = 0
    for k in range(d + 1):
        ways = (nCr(d, k) * fact[m - k]) % MOD

        if k % 2 == 1:
            total = (total - ways + MOD) % MOD
        else:
            total = (total + ways) % MOD

    return f"{total}\n"

