from collections import defaultdict
import heapq


def solve(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    graph = defaultdict(list)
    for i in range(1, m+1):
        u, v, x = map(int, lines[i].split())
        graph[u].append((v, x))
        graph[v].append((u, x))

    trains = []
    for i in range(m+1, m+1+k):
        s, y = map(int, lines[i].split())
        trains.append((s, y))

    # Compute shortest distances from city 1 using ONLY roads
    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Count how many train routes can be closed
    # A train to city s with cost y can be closed if road_dist[s] <= y
    closeable = 0
    for s, y in trains:
        if dist[s] <= y:
            closeable += 1

    return str(closeable) + '\n'


