    def compute_grundy(n, a, b, memo):
        if n < b:
            return 0
        if n in memo:
            return memo[n]

        reachable = set()

        if n >= a:
            for l in range(n - a + 1):
                r = n - a - l
                reachable.add(compute_grundy(l, a, b, memo) ^ compute_grundy(r, a, b, memo))

        if n >= b:
            for l in range(n - b + 1):
                r = n - b - l
                reachable.add(compute_grundy(l, a, b, memo) ^ compute_grundy(r, a, b, memo))

        mex = 0
        while mex in reachable:
            mex += 1

        memo[n] = mex
        return mex

