                y = int(parts[1])
                wires.append((x, y))
        except Exception as e:
            break

        if n <= 1:
            output_lines.append("0")
            continue

        # Union-Find to track connected components of contact points
        parent = {}

        def find(p):
            if p not in parent:
                parent[p] = p
            if parent[p] != p:
                parent[p] = find(parent[p])
            return parent[p]

        def union(p1, p2):
            r1 = find(p1)
            r2 = find(p2)
            if r1 != r2:
                parent[r1] = r2

        # Build the graph: wires connect contact points
        for x, y in wires:
            union(x, y)

        # Count connected components (consider only contact points on wires)
        roots = set()
        for x, y in wires:
            roots.add(find(x))

        num_components = len(roots)
        k = num_components - 1
        output_lines.append(str(k))

        # We need to merge k times
        if k > 0:
            # Get one representative contact point for each component
            root_to_sample = {}
            for x, y in wires:
                root = find(x)
                if root not in root_to_sample:
                    root_to_sample[root] = x

            # Track which wire contains representatives for each component
            root_to_wire = {}
            for i, (x, y) in enumerate(wires):
                root = find(x)
                if root not in root_to_wire:
                    root_to_wire[root] = i

            # Sort roots for deterministic output
            sorted_roots = sorted(root_to_wire.keys())

            # Merge consecutive components
            for i in range(k):
                curr_root = sorted_roots[i]
                next_root = sorted_roots[i + 1]

                wire_idx = root_to_wire[curr_root]
                x, y = wires[wire_idx]

                # Pick an old contact point to change
                # We can change either x or y (whichever is not needed for connectivity check)
                if find(x) == curr_root and find(y) == curr_root:
                    old_contact = y if x <= y else x
                else:
                    old_contact = y

                new_contact = root_to_sample[next_root]

                # Update the wire - change old_contact to new_contact
                if old_contact == x:
                    wires[wire_idx] = (new_contact, y)
                else:  # old_contact == y
                    wires[wire_idx] = (x, new_contact)

                # Output the change: wire_index (1-indexed), old, new
                wire_num = wire_idx + 1
                output_lines.append(f"{wire_num} {old_contact} {new_contact}")

