        while curr is not None:
            path.append(curr)
            curr = parent[curr]
        return path[::-1]

    # Find all vertices with degree >= 2
    degree = [0] * (n + 1)
    for v in range(1, n + 1):
        degree[v] = len(adj[v])

    # Test pairs from various strategic positions
    starts = [1, n, n//2]
