    def solve(u, parent_uses_coupon):
        """
        Returns a tuple of (count, min_cost) pairs for subtree rooted at u.
        parent_uses_coupon: whether parent's coupon was used (required for using u's coupon)
        """
        # Start with base options for node u
        result = {0: 0}

