            child_res_list = list(child_res.items())

            for cnt_child, cost_child in child_res_list:
                for cnt_base, cost_base in list(result.items()):
                    new_cnt = cnt_base + cnt_child
                    new_cost = cost_base + cost_child
                    if new_cnt > len(result) or result.get(new_cnt, INF) > new_cost:
                        result[new_cnt] = new_cost

        # Prune: remove dominated states
        # A state (count1, cost1) dominates (count2, cost2) if count1 >= count2 and cost1 <= cost2
        sorted_items = sorted(result.items(), key=lambda x: (x[0], x[1]))

        pruned = {}
        min_cost_so_far = INF
        for cnt, cost in sorted_items:
            # If this state has more items with same or lower cost, previous states are dominated
            if cost <= min_cost_so_far:
                min_cost_so_far = cost
                pruned[cnt] = cost

        return tuple(sorted(pruned.items()))

    # Compute solution for root (item 0 has no parent, so parent_uses_coupon=True)
    res = solve(0, True)

    # Find maximum items within budget
    ans = 0
    for cnt, cost in res:
        if cost <= b:
            ans = max(ans, cnt)

    return str(ans)

