def solution(input_string):
    MAX_N = 1000001
    MOD = 10**9 + 7

    lines = input_string.strip().split('\n')
    num_queries = int(lines[0])
    queries = []
    for i in range(1, num_queries + 1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))

    if not queries:
        return ""

    max_r = 0
    max_n = 0
    for r, n in queries:
        max_r = max(max_r, r)
        max_n = max(max_n, n)

    # Precompute divisors for all numbers up to max_n
    divisors = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for j in range(i, max_n + 1, i):
            divisors[j].append(i)

    # Precompute omega(n) - number of distinct prime factors
    omega = [0] * (max_n + 1)
    for i in range(2, max_n + 1):
        if omega[i] == 0:  # i is prime
            for j in range(i, max_n + 1, i):
                omega[j] += 1

    # f0[n] = 2^omega[n] (number of coprime factor pairs)
    f0 = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        f0[i] = pow(2, omega[i], MOD)

    # Memoize results: key is (r, n)
    memo = {}
    results = {}

    def compute_fr(r, n):
        if (r, n) in memo:
            return memo[(r, n)]

        if r == 0:
            memo[(0, n)] = f0[n]
            return memo[(0, n)]

        # fr(n) = sum(fr-1(d) for d in divisors of n)
        total = 0
        for d in divisors[n]:
            val = compute_fr(r - 1, d)
            total = (total + val) % MOD

        memo[(r, n)] = total
        return total

    # Answer queries
    output_lines = []
    for r, n in queries:
        output_lines.append(str(compute_fr(r, n)))

    return '\n'.join(output_lines)


